    'Every word found.': {ja:'すべての単語が見つかりました。', zh:'所有词都找到了。', ru:'Все слова найдены.', hi:'सारे शब्द मिल गए।', ur:'سارے الفاظ مل گئے۔', ar:'وُجدت كل الكلمات.'},
    'Game {n}': {ja:'第{n}ゲーム', zh:'第 {n} 局', ru:'Игра {n}', hi:'खेल {n}', ur:'کھیل {n}', ar:'اللعبة {n}'},
