    'Be Blue’s spymaster': {ja:'青のスパイマスターになる', zh:'当蓝队首领', ru:'Стать капитаном синих', hi:'नीले का स्पाईमास्टर बनें', ur:'نیلے کا اسپائی ماسٹر بنیں', ar:'كن رئيس جواسيس الأزرق'},
