    'Join Blue': {ja:'青に参加', zh:'加入蓝队', ru:'За синих', hi:'नीले में जुड़ें', ur:'نیلے میں شامل ہوں', ar:'انضم إلى الأزرق'},
    'nobody yet': {ja:'まだいません', zh:'暂时没人', ru:'пока никого', hi:'अभी कोई नहीं', ur:'ابھی کوئی نہیں', ar:'لا أحد بعد'},
    'Watching': {ja:'観戦中', zh:'观战', ru:'Смотрят', hi:'देख रहे हैं', ur:'دیکھ رہے ہیں', ar:'يشاهدون'},
    'Sit this one out': {ja:'今回は見学する', zh:'这局我旁观', ru:'Пропустить эту игру', hi:'इस बार बैठकर देखें', ur:'اس بار بیٹھ کر دیکھیں', ar:'سأجلس هذه المرة'},
    'Two sides. Ready when you are.': {ja:'2チームそろいました。準備ができたらどうぞ。', zh:'两队齐了，你准备好就开始。', ru:'Две команды. Начинайте, когда будете готовы.', hi:'दोनों पक्ष तैयार। जब आप तैयार हों।', ur:'دونوں طرفیں تیار۔ جب آپ تیار ہوں۔', ar:'فريقان جاهزان. ابدأ متى شئت.'},
